from openpyxl import load_workbook
from collections import defaultdict
import datetime

# Load the workbook and select the worksheet
wb = load_workbook("input.xlsx")
ws = wb["Sheet1"]

# Dictionary to store the most recent date for each (account, associated) pair
latest_dates = defaultdict(lambda: {"date": None, "rows": []})

# Iterate through the rows and collect data
for row in ws.iter_rows(min_row=3, max_col=7, values_only=True):
    account_number, associated_number, _, _, _, date, _ = row

    # Skip rows with no date in column E
    if not date:
        continue

    # Convert date to datetime object for comparison
    if isinstance(date, str):
        try:
            date = datetime.datetime.strptime(date, "%Y-%m-%d %H:%M:%S")
        except ValueError:
            continue  # Skip rows with invalid date format

    # Update the latest date for the (account, associated) pair
    key = (account_number, associated_number)
    if latest_dates[key]["date"] is None or date > latest_dates[key]["date"]:
        latest_dates[key] = {"date": date, "rows": [row]}
    elif date == latest_dates[key]["date"]:
        latest_dates[key]["rows"].append(row)

# Clear all existing data from the worksheet
for row in ws.iter_rows(min_row=3, max_col=7):
    for cell in row:
        cell.value = None

# Write the filtered data back to the worksheet
row_idx = 3
for key in latest_dates:
    for row_data in latest_dates[key]["rows"]:
        for col_idx, value in enumerate(row_data, start=1):
            ws.cell(row=row_idx, column=col_idx, value=value)
        row_idx += 1

# Save the workbook
wb.save("output.xlsx")
